//
// Note, for all intents and purposes this works like a regular stack!
//

static void elf_destroy_arena(elf_Arena *arena)
{
	sys_virtual_free(arena->data);
	zero_memory(arena, sizeof(*arena));
}

static elf_Arena elf_create_arena(u64 size)
{
	if (size == 0) {
		size = MEGABYTES(64);
	}
	elf_Arena arena = {};
	arena.size = size;
	arena.used = 0;
	arena.data = sys_virtual_alloc(size);
	return arena;
}

static void *elf_arena_push(elf_Arena *arena, u64 size)
{
	ASSERT(arena->used + size <= arena->size);
	void *data = arena->data + arena->used;
	arena->used += size;
	return data;
}

static void *elf_arena_push_zero(elf_Arena *arena, u64 size)
{
	void *data = elf_arena_push(arena, size);
	zero_memory(data, size);
	return data;
}

static void *elf_arena_push_copy(elf_Arena *arena, u64 size, const void *data)
{
	void *copy = elf_arena_push(arena, size);
	copy_memory(copy, data, size);
	return copy;
}

static char *elf_arena_push_string_data_copy(elf_Arena *arena, u64 size, const char *data)
{
	if (size == 0) {
		size = strlen(data);
	}
	void *copy = elf_arena_push(arena, size + 1);
	copy_memory(copy, data, size + 1);
	return copy;
}
